  override hook(): void {}
}
`))).toEqual([expect.stringMatching(/exported class method 'Impl.hook' .* has no JSDoc\./)])
  })

  it('treats an underscore-prefixed rename of a base parameter as the same parameter', () => {
    expect(collectExportJsdocViolations(make(`
